  /**
   * @method
   * @name hibachi#fetchFundingRateHistory
   * @description fetches historical funding rate prices
   * @see https://api-doc.hibachi.xyz/#079586af-0d94-41ea-99bb-7afcd93bf438
   * @param {string} symbol unified symbol of the market to fetch the funding
   * rate history for
   * @param {int} [since] timestamp in ms of the earliest funding rate to fetch
   * @param {int} [limit] the maximum amount of [funding rate structures]{@link
   * https://docs.ccxt.com/?id=funding-rate-history-structure} to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} a list of [funding rate structures]{@link
   * https://docs.ccxt.com/?id=funding-rate-history-structure}
   */
  std::shared_future<std::any> fetchFundingRateHistory(
      std::any symbol = std::any{}, std::any since = std::any{},
      std::any limit = std::any{}, std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 std::any response =
                     awaitValue(this->publicGetMarketDataFundingRates(
                         this->extend(request, params)));
                 //
                 // {
                 //     "data": [
                 //         {
                 //             "contractId": 2,
                 //             "fundingTimestamp": 1753488000,
                 //             "fundingRate": "0.000137",
                 //             "indexPrice": "117623.65010"
                 //         }
                 //     ]
                 // }
                 //
                 std::any data = this->safeList(response, std::string("data"),
                                                ccxt::list{});
                 std::any rates = ccxt::list{};
                 for (std::any i = 0; isLessThan(i, getArrayLength(data));
                      postFixIncrement(i)) {
                   std::any entry = ::getValue(data, i);
                   std::any timestamp = this->safeIntegerProduct(
                       entry, std::string("fundingTimestamp"), 1000);
                   arrayPush(
                       rates,
                       ccxt::dict{
                           {std::string("info"), entry},
                           {std::string("symbol"), symbol},
                           {std::string("fundingRate"),
                            this->safeNumber(entry,
                                             std::string("fundingRate"))},
                           {std::string("timestamp"), timestamp},
                           {std::string("datetime"), this->iso8601(timestamp)},
                       });
                 }
                 std::any sorted =
                     this->sortBy(rates, std::string("timestamp"));
                 return this->filterBySymbolSinceLimit(sorted, symbol, since,
                                                       limit);
               })
        .share();
  }
